const IMAGINE_DATA_V2 = {"neuronio":{"lead":"Como uma mensagem atravessa um neurônio, cruza um espaço vazio e continua no neurônio seguinte?","hierarchy":["rede neural","neurônio","dendrito / soma / axônio","membrana","canais, receptores e íons"],"scene_title":"A comporta que só abre de uma vez","scene":["Imagine uma bacia alimentada por muitos córregos pequenos. Nenhum deles sozinho enche nada; o que conta é quanta água chega junto. Na saída da bacia existe uma comporta que não tem meio-termo: enquanto o nível está baixo ela fica fechada, e quando o nível alcança certa altura ela abre inteira, sempre da mesma maneira.","A onda que escapa desce por um canal comprido. Ao longo dele há bombas que reerguem a onda a cada trecho, então ela chega ao fim com a mesma força com que saiu. E no fim o canal simplesmente acaba: existe um vão. A água não o atravessa — a carga é passada de barco até a doca do outro lado, e só encaixa onde o formato corresponde."],"mapping":[["Dendritos","PARTE CELULAR","os córregos que trazem água"],["Soma","PARTE CELULAR","a bacia onde a água se acumula"],["Limiar","CRITÉRIO","a altura em que a comporta cede"],["Potencial de ação","PROCESSO","a onda que desce o canal, sempre igual"],["Axônio","PARTE CELULAR","o canal"],["Canal iônico","PROTEÍNA","as bombas que reerguem a onda a cada trecho"],["Fenda sináptica","ESPAÇO","o vão onde o canal acaba"],["Neurotransmissor","MOLÉCULA","a carga levada de barco"],["Receptor","PROTEÍNA","o encaixe da doca, que só aceita o formato certo"]],"chain":["Entradas sinápticas alteram a voltagem da membrana.","Ao alcançar o limiar, canais geram o potencial de ação.","O sinal percorre o axônio até o terminal.","A entrada de Ca²⁺ favorece a fusão das vesículas.","Neurotransmissores atravessam a fenda e ativam receptores.","O neurônio seguinte muda sua atividade elétrica."],"ifs":[["E se a comporta cedesse um pouquinho para cada córrego?","Não haveria onda — a água escorreria de forma contínua e iria perdendo força com a distância. É justamente o tudo-ou-nada que permite ao sinal viajar longe sem se degradar."],["E se as bombas do canal não disparassem em sequência?","A onda partiria forte e chegaria fraca ao fim. Ela não é empurrada de uma vez: é refeita a cada trecho."],["E se a carga chegasse a uma doca de outro formato?","Chegaria ao outro lado sem produzir efeito. Atravessar o vão não basta; o efeito depende de haver encaixe."]],"keep":"A bacia enche → a comporta abre inteira ou não abre → a onda desce sem enfraquecer → e o vão do fim é atravessado de barco."},"recompensa":{"lead":"Como o cérebro aprende que uma pista, uma ação ou um resultado merece mais atenção e esforço?","hierarchy":["pista e resultado","VTA e estriado","sinal dopaminérgico","erro de previsão","atualização de valor e ação"],"scene_title":"A rota que ganha ou perde valor","scene":["Imagine um GPS que prevê quanto uma rota vai custar e quanto benefício ela deve entregar. Antes de agir, ele cria uma expectativa. Depois compara essa previsão com o resultado real.","Se o resultado é melhor que o previsto, aumenta o valor da rota; se é igual, quase não recalcula; se é pior, reduz o valor. Com repetição, as placas que anunciam a rota passam a ganhar poder motivacional antes mesmo da chegada."],"mapping":[["Pista","EVENTO","a placa que anuncia a rota"],["Expectativa","REPRESENTAÇÃO","o benefício previsto para a rota"],["Resultado","EVENTO","o benefício realmente encontrado no fim da rota"],["Erro de previsão","PROCESSO","a diferença que faz o GPS recalcular a rota"],["Dopamina","NEUROMODULADOR","parte do sinal de recálculo"],["Estriado","CIRCUITO","o registro que favorece repetir ou abandonar a rota"]],"chain":["Uma pista ativa uma expectativa.","O cérebro estima o valor provável do resultado.","O resultado real é comparado com a previsão.","A diferença modifica sinais de aprendizagem.","Conexões entre pista, ação e resultado são atualizadas.","Na próxima tentativa, a escolha e a motivação mudam."],"ifs":[["E se o resultado fosse sempre exatamente o esperado?","O GPS manteria praticamente o mesmo valor para a rota, porque previsto e encontrado coincidiriam."],["E se a recompensa prometida deixasse de aparecer?","A cada chegada vazia, o GPS reduziria o valor da rota e as placas perderiam força para puxar a próxima escolha."]],"keep":"A placa anuncia a rota → o GPS prevê o resultado → compara com a chegada → aumenta ou reduz o valor da rota para a próxima viagem."},"decisao":{"lead":"Como o cérebro compara coisas incompatíveis, desconta seus custos e fecha uma escolha?","hierarchy":["opções","OFC / vmPFC","valor subjetivo","descontos de tempo, esforço e risco","acúmulo de evidência","limiar"],"scene_title":"O leilão com uma moeda interna","scene":["Imagine uma casa de leilões que recebe objetos sem preço comum: descanso, comida, dinheiro e tempo. Um avaliador converte tudo para uma moeda interna que depende do estado atual.","Antes do lance final, cada opção paga taxas: esperar, esforçar-se e correr risco reduzem seu valor. Os lances vão se acumulando; quando um deles cruza o valor mínimo exigido, o leilão fecha. O resultado depois volta ao avaliador e corrige preços futuros."],"mapping":[["Valor subjetivo","REPRESENTAÇÃO","a moeda usada dentro da casa de leilões"],["OFC / vmPFC","ESTRUTURAS","o avaliador que converte e atualiza"],["Desconto temporal","PROCESSO","a taxa cobrada pela espera"],["Custo de esforço","PROCESSO","a taxa cobrada pelo trabalho"],["Aversão à perda","VIÉS / PROCESSO","o peso extra atribuído à perda"],["Acúmulo de evidência","PROCESSO","os lances subindo"],["Limiar","CRITÉRIO","o valor necessário para fechar"]],"chain":["Opções diferentes são convertidas para valor subjetivo.","Tempo, esforço e risco descontam cada valor.","Evidências a favor das alternativas se acumulam.","Ruído e semelhança entre opções alteram a velocidade da rampa.","A escolha ocorre quando uma alternativa cruza o limiar.","O resultado corrige a avaliação para decisões futuras."],"ifs":[["E se duas opções tivessem praticamente o mesmo valor?","Os dois lances subiriam quase juntos; nenhum abriria distância e o leilão demoraria mais para fechar."],["E se o valor mínimo para fechar fosse reduzido?","O primeiro lance cruzaria o mínimo mais cedo, mas o leilão encerraria com menos comparação entre os lotes."]],"limit":"O cérebro não converte conscientemente tudo em números únicos. O modelo descreve sinais distribuídos, dependentes do contexto e da tarefa.","keep":"Tudo vira a mesma moeda → cada opção paga suas taxas → os lances sobem → o primeiro a cruzar o mínimo leva o leilão → e o avaliador corrige os preços da próxima vez."},"atencao":{"lead":"Como o cérebro mantém uma meta ativa quando existem mais estímulos e respostas possíveis do que podem ocupar o centro da ação?","hierarchy":["prontidão","seleção","meta ativa","capacidade limitada","proteção contra concorrentes","troca de regra"],"scene_title":"A bancada com espaço limitado","scene":["Imagine uma oficina com uma bancada estreita. A luz geral precisa estar acesa para qualquer trabalho começar. Entre várias caixas, o mecânico aproxima apenas a caixa necessária e prende na borda um cartão com a tarefa atual. No centro da bancada cabem poucas peças e apenas uma ferramenta pode operar com precisão de cada vez.","Peças de outros serviços ficam em bandejas laterais para não invadir o centro. Quando surge um conflito, o mecânico compara o cartão, afasta a peça concorrente e mantém a sequência. Trocar de serviço exige guardar as peças atuais, buscar outra caixa, trocar o cartão e preparar outra ferramenta; essa reorganização consome tempo mesmo quando os dois serviços são simples."],"mapping":[["Alerta","FUNÇÃO","a luz geral acesa na oficina"],["Orientação","FUNÇÃO","aproximar a caixa escolhida da bancada"],["Objetivo","REPRESENTAÇÃO","o cartão preso na borda"],["Memória de trabalho","FUNÇÃO","as poucas peças mantidas no centro da bancada"],["Inibição","FUNÇÃO","as bandejas que mantêm peças concorrentes fora do centro"],["Controle executivo","FUNÇÃO","comparar o cartão, retirar conflitos e organizar a próxima ação"]],"chain":["A prontidão geral permite responder.","Uma fonte ou localização é priorizada.","A meta e poucas informações permanecem ativas.","Representações concorrentes são reduzidas.","Conflitos são resolvidos conforme a regra atual.","Uma troca exige reconfigurar meta, regra e resposta."],"ifs":[["E se todas as peças fossem despejadas no centro da bancada?","As peças cobririam umas às outras, a ferramenta perderia espaço para operar e aumentariam as trocas e os erros."],["E se o cartão e a caixa fossem trocados a cada poucos segundos?","A oficina passaria grande parte do tempo guardando peças, buscando caixas e preparando ferramentas, em vez de concluir o serviço."]],"limit":"A bancada não representa uma bateria única nem uma região isolada. A capacidade de manter controle depende de redes distribuídas, da tarefa, do sono, da motivação, do estresse e da interferência.","keep":"A luz acende → uma caixa chega à bancada → o cartão mantém o serviço atual → poucas peças ocupam o centro → bandejas seguram concorrentes → trocar exige reorganizar tudo."},"emocao":{"lead":"Como um acontecimento muda o corpo, a atenção e a decisão — e por que o mesmo sistema pode ajudar ou atrapalhar?","hierarchy":["evento relevante","amígdala e córtex","hipotálamo","sistema autônomo e eixo HPA","estado corporal","regulação"],"scene_title":"A casa que muda de modo, não de dono","scene":["Imagine uma casa com vários modos de funcionamento. Sensores na entrada classificam o que chega: isto importa, isto não. Quando algo é classificado como importante, um painel troca o modo da casa — muda a potência disponível, a circulação, o que fica acessível e o que fica em espera.","Trocar de modo é útil e reversível. O problema aparece quando a casa fica presa no modo de emergência: manter tudo em potência máxima consome o que deveria durar e reduz a margem para lidar com o que vier depois. Por isso alguém continua lendo o contexto e decidindo se o modo se mantém, baixa ou muda. Ninguém tomou a casa — ela está no mesmo lugar, operando de outro jeito."],"mapping":[["Amígdala","ESTRUTURA","os sensores que classificam o que chega"],["Hipotálamo","ESTRUTURA","o painel que troca o modo"],["Sistema autônomo","SISTEMA","os ajustes imediatos de potência e circulação"],["Eixo HPA","PROCESSO","a ordem lenta que sustenta o modo por mais tempo"],["Cortisol","HORMÔNIO","a energia liberada para sustentar o modo"],["Córtex pré-frontal","REDE / ESTRUTURA","quem lê o contexto e decide se o modo continua"],["Estado emocional","ESTADO DE REDE E CORPO","a casa inteira operando em um dos modos disponíveis"]],"chain":["Um estímulo é avaliado quanto à relevância.","Amígdala, córtex e memória influenciam a interpretação.","O hipotálamo aciona respostas autonômicas e hormonais.","O estado corporal muda atenção e disponibilidade de energia.","O córtex usa contexto e objetivos para regular a resposta.","Feedback corporal e hormonal favorece recuperação."],"ifs":[["E se qualquer barulho trocasse a casa para o modo de emergência?","A casa gastaria potência com quase tudo e perderia a capacidade de distinguir o que era mesmo urgente."],["E se a casa entrasse no modo e não conseguisse sair?","Os sistemas mantidos em potência máxima se desgastariam, e sobraria pouca margem para a próxima demanda. É essa permanência, e não a troca de modo, que descreve o estresse crônico."]],"limit":"A amígdala não é um botão de medo e o cortisol não é veneno: os efeitos dependem de intensidade, duração e contexto. E não existe um morador separado lendo o contexto — a avaliação é feita pelas mesmas redes que produzem a emoção.","keep":"Emoção é avaliação + corpo + ação possível — outro modo da mesma casa, não o oposto da razão."},"autonomo":{"lead":"Como o corpo coordena coração, pulmões, digestão e glândulas sem pedir uma decisão consciente a cada segundo?","hierarchy":["SNC","neurônio pré-ganglionar","gânglio autonômico","neurônio pós-ganglionar","órgão","feedback visceral"],"scene_title":"A administração automática de um edifício vivo","scene":["Imagine um edifício com uma administração automática. Uma rede central consegue espalhar rapidamente o mesmo aviso por vários setores: é o simpático, útil para mobilização em bloco. Outra rede possui controles próximos de cada setor: é o parassimpático, capaz de ajustar coração, digestão e pupilas de maneira mais seletiva.","O nervo vago funciona em grande parte como uma linha de telemetria: leva ao centro informações sobre o estado dos órgãos. O intestino tem ainda uma administração local, capaz de coordenar muito da digestão por conta própria."],"mapping":[["Simpático","RAMO AUTONÔMICO","a rede central de mobilização"],["Parassimpático","RAMO AUTONÔMICO","os controles locais de conservação"],["Gânglio autonômico","ESTRUTURA","a estação de troca entre dois neurônios"],["Medula adrenal","ESTRUTURA","o alto-falante que lança adrenalina no sangue"],["Nervo vago","NERVO","a grande linha de controle e telemetria"],["Sistema entérico","REDE NEURAL","a administração local do intestino"],["Tônus autonômico","ESTADO","o equilíbrio momentâneo entre os ramos"]],"chain":["Centros no cérebro e na medula geram comandos autonômicos.","Um neurônio pré-ganglionar alcança um gânglio.","O neurônio pós-ganglionar leva o sinal ao órgão.","Simpático e parassimpático alteram funções conforme a demanda.","Sinais viscerais retornam ao cérebro, sobretudo por vias como o vago.","O equilíbrio muda continuamente em vez de alternar entre dois botões absolutos."],"ifs":[["E se o simpático agisse em apenas um ponto isolado durante uma emergência?","A mobilização de coração, pulmões e circulação perderia coordenação."],["E se o cérebro só mandasse ordens e não recebesse telemetria do corpo?","A regulação não conseguiria corrigir-se com base no estado real dos órgãos."]],"limit":"Simpático não significa ruim e parassimpático não significa sempre calmo. Ambos permanecem ativos e podem produzir efeitos diferentes conforme o órgão.","keep":"A administração mantém dois ramos ativos → uma estação liga cada cadeia → os órgãos mudam → e a telemetria volta ao centro para corrigir o edifício."},"sono":{"lead":"Por que dormir não é desligar, mas mudar o tipo de trabalho realizado pelo cérebro?","hierarchy":["ritmo circadiano e pressão de sono","ciclos NREM / REM","padrões de atividade","replay e ajuste sináptico","consolidação e recuperação"],"scene_title":"A noite em que a trilha vira caminho","scene":["Durante o dia você atravessa um campo aberto muitas vezes. Cada passagem deixa uma marca fraca na grama — nenhuma delas é ainda um caminho, e todas somem se ninguém voltar ali.","À noite, equipes percorrem de novo as marcas mais usadas do dia. O que é repisado ganha terreno firme e se conecta às estradas que já existiam; o que não é repisado desaparece. As equipes passam várias vezes, em turnos de tipos diferentes, e o resultado depende da noite inteira, não de um turno só. Nada foi transportado para lugar nenhum: o próprio terreno mudou de forma."],"mapping":[["Ritmo circadiano","PROCESSO","o relógio que abre o expediente da noite"],["Pressão homeostática","PROCESSO","o quanto de campo pisado ficou por revisar"],["NREM","ESTADO","os turnos que firmam terreno"],["REM","ESTADO","os turnos que ligam trilhas novas às estradas antigas"],["Replay","PROCESSO","repisar de novo as marcas do dia"],["Hipocampo","ESTRUTURA","o registro fresco de por onde se passou"],["Córtex","REDE","a malha de estradas já consolidada"]],"chain":["Relógio circadiano e pressão tornam o sono provável.","O cérebro percorre ciclos com padrões diferentes.","Redes reativam partes de experiências recentes.","Hipocampo, córtex e outras regiões reorganizam representações.","Sinapses são recalibradas e ocorre manutenção metabólica.","O desempenho posterior reflete o processo integrado."],"ifs":[["E se ninguém repisasse as marcas do dia?","Elas sumiriam, e as poucas que restassem ficariam soltas, sem ligação com as estradas existentes. Não é que a experiência não tenha acontecido — é que ela não virou terreno."],["E se todas as marcas fossem reforçadas igualmente?","O campo viraria uma malha uniforme, sem hierarquia. Reforçar tudo equivale a não distinguir nada: parte do trabalho da noite é justamente deixar enfraquecer."]],"keep":"De dia você cruza o campo; de noite o que foi mais usado vira caminho e o resto some."},"neuroanatomia":{"lead":"Como localizar estruturas sem cair na falsa ideia de que cada função mora em uma única gaveta?","hierarchy":["sistema nervoso","encéfalo","córtex e estruturas subcorticais","substância branca","redes funcionais"],"scene_title":"A cidade dos bairros conectados","scene":["Imagine o encéfalo como uma cidade com bairros especializados, estações reguladoras, centros de comparação e grandes vias. Saber o endereço ajuda, mas não explica sozinho o serviço.","Falar, lembrar ou alcançar um objeto exige cooperação entre bairros. As estradas importam tanto quanto os prédios: uma conexão interrompida pode impedir que regiões preservadas trabalhem juntas."],"mapping":[["Lobos corticais","ESTRUTURAS","os bairros da cidade, com especializações relativas"],["Substância branca","TECIDO / VIAS","as grandes vias que conectam bairros"],["Tálamo","ESTRUTURA","a estação que regula parte do tráfego"],["Gânglios da base","CIRCUITOS","os cruzamentos que ajudam a liberar rotas de ação"],["Cerebelo","ESTRUTURA","o centro que compara o trajeto planejado com o realizado"],["Tronco encefálico","ESTRUTURA","a infraestrutura vital que mantém a cidade funcionando"],["Rede funcional","REDE","bairros e vias cooperando para entregar um serviço"]],"chain":["Uma tarefa recruta regiões com contribuições diferentes.","Vias de substância branca permitem troca de informação.","Estruturas subcorticais regulam fluxo, estado e seleção.","O padrão conjunto produz a operação.","Lesões em pontos diferentes alteram etapas diferentes da mesma função."],"ifs":[["E se todos os bairros estivessem preservados, mas uma grande via fosse cortada?","Os prédios continuariam de pé, mas serviços que exigem troca entre bairros falhariam porque a cidade perdeu a ligação."],["E se cada bairro prestasse somente um serviço?","Um dano teria efeito único e previsível; na cidade real, os mesmos bairros entram em combinações diferentes conforme a tarefa."]],"keep":"Na cidade, o endereço mostra onde fica um bairro; as vias e o tráfego mostram como vários bairros conseguem trabalhar juntos."},"sensorial":{"lead":"Como luz, vibração, pressão e moléculas se transformam em uma experiência perceptiva?","hierarchy":["estímulo físico ou químico","receptor","transdução","vias sensoriais","córtex e redes","percepção e ação"],"scene_title":"O estúdio de tradução multimídia","scene":["Imagine um estúdio que recebe materiais em formatos incompatíveis: luz, vibração, pressão e química. Cada cabine possui tradutores especializados que convertem seu formato para sinais elétricos.","Depois da tradução, equipes analisam contraste, frequência, posição e mudança. O produto final não é uma cópia bruta, mas uma reconstrução guiada também por atenção, memória e expectativa."],"mapping":[["Estímulo","EVENTO FÍSICO / QUÍMICO","o material que chega ao estúdio em um formato específico"],["Receptor sensorial","CÉLULA / PROTEÍNA","o tradutor especializado"],["Transdução","PROCESSO","a conversão para sinal neural"],["Vias sensoriais","VIAS","os canais de transmissão"],["Tálamo","ESTRUTURA","a estação reguladora de grande parte do tráfego"],["Percepção","PROCESSO","o produto reconstruído"]],"chain":["O estímulo alcança receptores especializados.","A transdução produz uma mudança elétrica.","Vias codificam intensidade, posição e tempo.","Núcleos e córtices extraem características.","Memória, atenção e contexto restringem interpretações.","A percepção orienta ação e nova coleta de informação."],"ifs":[["E se o receptor respondesse à energia errada?","A modalidade perderia seletividade e o sinal deixaria de representar adequadamente o estímulo."],["E se a interpretação ignorasse contexto e memória?","Sinais ambíguos seriam resolvidos de maneira menos eficiente."]],"limit":"A percepção é construída, mas não inventada livremente. Ela é limitada pelo estímulo, pela anatomia e pela aprendizagem.","keep":"Cada cabine do estúdio traduz seu formato para a mesma língua elétrica — e o que sai não é cópia do que entrou, é reconstrução."},"motor":{"lead":"Como uma intenção vira movimento coordenado e é corrigida enquanto acontece?","hierarchy":["objetivo","áreas associativas e pré-motoras","gânglios da base e cerebelo","córtex motor","medula e neurônio motor","músculo e feedback"],"scene_title":"A orquestra que se escuta enquanto toca","scene":["Imagine uma orquestra que executa uma peça em tempo real. Uma equipe organiza a sequência, outra ajuda a liberar o programa adequado e os instrumentos recebem comandos específicos.","Enquanto toca, a orquestra escuta o próprio resultado. Um sistema de comparação detecta atraso, força ou direção inadequados e corrige a execução. Com treino, a sequência exige menos controle consciente detalhado."],"mapping":[["Objetivo","REPRESENTAÇÃO","a partitura que orienta a orquestra"],["Áreas pré-motoras","ESTRUTURAS","a preparação da sequência"],["Gânglios da base","CIRCUITOS","a seleção do programa"],["Córtex motor","ESTRUTURA","a contribuição para comandos descendentes"],["Medula / neurônio motor","VIA / CÉLULA","a distribuição final"],["Músculo","TECIDO","o instrumento que produz a ação"],["Cerebelo","ESTRUTURA","a comparação e correção"]],"chain":["Um objetivo define o resultado desejado.","Redes pré-motoras organizam possibilidades.","Gânglios da base ajudam a selecionar e iniciar.","Comandos descem por tronco e medula.","Músculos produzem movimento e sensores relatam o resultado.","Cerebelo e outras redes comparam, corrigem e aprendem."],"ifs":[["E se a orquestra tocasse sem escutar o próprio som?","Os instrumentos ainda começariam a peça, mas atrasos, força e direção inadequados seriam corrigidos pior durante a execução."],["E se todas as partituras fossem liberadas ao mesmo tempo?","Os instrumentos receberiam sequências concorrentes e a orquestra perderia coordenação."]],"keep":"A orquestra recebe a peça, libera o programa e toca — e vai corrigindo porque escuta o próprio som enquanto ele acontece."},"desenvolvimento":{"lead":"Como o sistema nervoso constrói células, posições e conexões — e depois refina o excesso?","hierarchy":["genes, sinais e ambiente","proliferação","migração e diferenciação","crescimento axonal e sinapses","mielinização e poda","plasticidade"],"scene_title":"O canteiro que produz mais do que vai ficar","scene":["Um canteiro de obras começa produzindo trabalhadores e material muito além do que a obra final vai usar. Eles são despachados para regiões diferentes e, pelo lugar onde chegam e pelo que encontram lá, recebem sua função. Depois abrem rotas até os pontos com que precisam falar.","No começo existem muito mais rotas do que vão permanecer. O que decide quais ficam não é a planta: é o uso. As rotas por onde o movimento realmente passa são pavimentadas e ganham revestimento que as deixa rápidas; as que quase não recebem movimento são desfeitas e o material volta a circular. Enquanto o canteiro está aberto, refazer um trecho é barato; depois fica mais caro — mas ele nunca fecha de vez."],"mapping":[["Proliferação","PROCESSO","o canteiro produzindo trabalhadores e material além do necessário"],["Migração","PROCESSO","o despacho de cada um para sua região"],["Diferenciação","PROCESSO","a função que se recebe pelo lugar de chegada e pelo que há nele"],["Crescimento axonal","PROCESSO","abrir a rota até o ponto com que se precisa falar"],["Sinaptogênese","PROCESSO","abrir muito mais rotas do que vão permanecer"],["Poda","PROCESSO","desfazer as rotas sem movimento e devolver o material"],["Mielinização","PROCESSO","o revestimento que deixa rápidas as rotas que ficaram"]],"chain":["Células precursoras proliferam.","Sinais orientam migração e identidade.","Axônios crescem e encontram alvos.","Sinapses são formadas em excesso.","Atividade estabiliza alguns padrões.","Poda e mielinização refinam redes ao longo do tempo."],"ifs":[["E se nenhuma rota fosse desfeita?","O canteiro entregaria uma malha densa e indistinta, em que tudo se liga a tudo com pouca força. O excesso inicial só vira precisão porque parte dele é devolvida."],["E se a planta decidisse as rotas, em vez do movimento?","O resultado final seria o mesmo em qualquer lugar, independentemente do que aquele ambiente de fato exige. É o uso que ajusta a obra ao mundo onde ela está."]],"keep":"O canteiro produz demais de propósito → o uso escolhe o que fica → o que fica é revestido → e refazer nunca deixa de ser possível, só fica mais caro."},"linguagem":{"lead":"Como sons e símbolos se transformam em significado, sequência e ação comunicativa?","hierarchy":["som, gesto ou escrita","análise sensorial","palavras e significado","sintaxe e planejamento","fala / escrita / gesto","feedback"],"scene_title":"A redação conectada em tempo real","scene":["Imagine uma redação que recebe áudio, texto, imagens e contexto. Uma equipe identifica unidades; outra acessa significados; outra organiza relações e intenção; equipes motoras preparam a publicação.","Nenhum setor trabalha sozinho. Enquanto uma frase é produzida, a própria saída é monitorada pelo som, pela visão e pela sensação dos movimentos. Uma falha nas conexões pode impedir a cooperação mesmo com setores preservados."],"mapping":[["Sistemas sensoriais","REDES","a equipe que recebe materiais na redação"],["Redes temporais","ESTRUTURAS / REDES","análise de formas e significados"],["Redes frontais","ESTRUTURAS / REDES","organização, seleção e planejamento"],["Fascículos","VIAS","os canais entre equipes"],["Sistemas motores","REDES","o setor de publicação"],["Prosódia e contexto","PROCESSOS","a edição de tom e intenção"],["Feedback","PROCESSO","a revisão em tempo real"]],"chain":["O sinal é analisado pelos sistemas sensoriais.","Redes reconhecem padrões e acessam palavras.","Conhecimento semântico e contexto restringem interpretações.","Redes frontotemporais organizam sequência e intenção.","Sistemas motores produzem fala, escrita ou gesto.","Feedback permite correção."],"ifs":[["E se compreensão e produção fossem duas caixas totalmente independentes?","A comunicação entre significado, planejamento e monitoramento seria inexplicável."],["E se as regiões estivessem intactas, mas o fascículo de conexão fosse lesionado?","Os canais entre as equipes da redação deixariam de levar conteúdo de um setor ao outro, apesar de cada setor continuar preservado."]],"limit":"Broca e Wernicke são referências históricas úteis, não os dois únicos centros da linguagem. A função depende de redes amplas.","keep":"A redação recebe, reconhece, dá sentido, organiza e publica — e vai revisando a própria publicação enquanto ela sai."},"clinica":{"lead":"Por que alterações cerebrais diferentes podem produzir sintomas parecidos — e sintomas semelhantes não revelam sozinhos a causa?","hierarchy":["tecido e circuito","mecanismo de alteração","função afetada","sinais e sintomas","avaliação clínica"],"scene_title":"O carro que não pega, por quatro motivos diferentes","scene":["Um carro não liga. Pode ser que o combustível tenha parado de chegar; pode ser que uma peça venha se desgastando há meses; pode ser que a ignição esteja disparando fora de sincronia; ou pode ser que um fio tenha se rompido entre duas partes que continuam perfeitas.","As quatro avarias produzem a mesma frase — “não pega” — por caminhos completamente diferentes. E o carro costuma disfarçar: com uma peça se desgastando devagar, ele ainda anda por um tempo puxando de onde dá, e o dono só percebe quando não há mais de onde puxar."],"mapping":[["Isquemia","PROCESSO PATOLÓGICO","o combustível que parou de chegar"],["Degeneração","PROCESSO PATOLÓGICO","a peça que se desgasta ao longo de meses"],["Hiperssincronia","PADRÃO DE REDE","a ignição disparando fora de sincronia"],["Lesão de via","ALTERAÇÃO ESTRUTURAL","o fio rompido entre duas partes intactas"],["Compensação","PROCESSO","o carro puxando de onde ainda dá"],["Sintoma","MANIFESTAÇÃO","o “não pega”"],["Diagnóstico","PROCESSO CLÍNICO","separar qual das avarias produziu aquilo"]],"chain":["Uma alteração afeta tecido ou circuito.","A rede perde ou modifica uma operação.","Outras redes compensam ou se desorganizam.","Surgem sinais e sintomas dependentes de local, intensidade e tempo.","História, exame e testes comparam hipóteses.","Intervenção é definida conforme mecanismo e pessoa."],"ifs":[["E se duas avarias diferentes produzissem o mesmo “não pega”?","Produzem — e é exatamente por isso que o sintoma sozinho não identifica a causa. O exame existe para separar hipóteses que a queixa não separa."],["E se a peça se desgastasse bem devagar?","A compensação esconderia a falha por um bom tempo, e o problema apareceria de repente para o dono, embora viesse acontecendo há meses."]],"limit":"A metáfora é educativa, não diagnóstica: um carro tem poucas avarias possíveis e um cérebro não. Sintomas têm muitas causas e exigem avaliação profissional.","keep":"O sintoma é o carro não pegando; o mecanismo é qual das avarias produziu isso."},"farmacologia":{"lead":"Como uma molécula altera uma sinapse e por que o efeito final não pode ser deduzido apenas pelo nome do neurotransmissor?","hierarchy":["molécula administrada","distribuição","receptor / transportador / canal / enzima","sinapse e circuito","efeito","adaptação"],"scene_title":"A fechadura que se acostuma","scene":["Uma porta com uma fechadura de formato específico. Certas chaves entram e giram: a porta abre. Outras entram, não giram e ainda ocupam o buraco — enquanto estiverem ali, a chave que abriria não entra. Nos dois casos o encaixe é o mesmo; o que muda é o que acontece depois de encaixar.","As chaves usadas não ficam no capacho para sempre: uma equipe recolhe o que sobrou e alguém lima as que não servem mais. Atrasar o recolhimento faz as chaves ficarem por perto mais tempo — o que não é a mesma coisa que distribuir mais chaves, embora as duas aumentem a chance de a porta abrir. E se a mesma chave chega todo dia, a fechadura vai respondendo menos: cede menos ao mesmo giro, e parte delas é retirada da porta. Passa a ser preciso mais chave para o mesmo resultado — e quem parou de receber chave de repente fica com fechaduras demais esperando uma que não vem."],"mapping":[["Receptor","PROTEÍNA","a fechadura, com seu formato específico"],["Agonista","AÇÃO FARMACOLÓGICA","a chave que entra e gira"],["Antagonista","AÇÃO FARMACOLÓGICA","a chave que entra, não gira e ocupa o lugar"],["Transportador","PROTEÍNA","a equipe que recolhe o que sobrou"],["Enzima","PROTEÍNA","quem lima as chaves até não servirem"],["Inibidor de recaptação","AÇÃO FARMACOLÓGICA","atrasar o recolhimento"],["Tolerância","PROCESSO ADAPTATIVO","a fechadura cedendo cada vez menos à mesma chave"]],"chain":["A molécula alcança o sistema nervoso em certa concentração.","Interage com um alvo molecular.","Muda intensidade, duração ou direção da sinalização.","Circuitos alteram sua atividade.","Surgem efeitos funcionais e efeitos adversos.","Exposição repetida pode produzir adaptações homeostáticas."],"ifs":[["E se atrasar o recolhimento fosse igual a distribuir mais chaves?","As duas coisas aumentam a chance de a porta abrir, mas por caminhos distintos: uma prolonga o que já foi entregue, a outra muda quanto se entrega. A dinâmica no tempo não é a mesma."],["E se a fechadura nunca mudasse com a repetição?","A mesma chave abriria a porta com a mesma facilidade para sempre. Como ela muda, é preciso mais chave para o mesmo efeito — e é por isso que parar de repente deixa fechaduras demais sem chave nenhuma."]],"limit":"Fármacos não são chaves perfeitas: encaixam em mais de uma fechadura, e o efeito clínico depende de dose, tempo, organismo e circuito — não apenas do alvo molecular.","keep":"A chave encaixa → gira ou só ocupa → o que sobra é recolhido → e a fechadura vai cedendo cada vez menos à mesma chave."},"metodos":{"lead":"Como saber o que um método realmente mede e até onde uma conclusão pode ir?","hierarchy":["pergunta","método","sinal coletado","análise","inferência","convergência"],"scene_title":"A equipe de câmeras e instrumentos","scene":["Imagine um evento complexo registrado por ferramentas diferentes. Uma câmera é muito rápida, mas localiza mal. Outra mostra melhor o local, porém registra com atraso. Um microfone próximo capta poucas pessoas com grande detalhe.","Uma intervenção altera temporariamente uma parte do evento para observar o que muda. Nenhuma ferramenta registra tudo; confiança aumenta quando métodos com limitações diferentes sustentam o mesmo modelo."],"mapping":[["EEG","TÉCNICA","a câmera rápida usada pela equipe, com localização limitada"],["fMRI","TÉCNICA","o mapa espacial indireto e lento"],["Registro unitário","TÉCNICA","o microfone perto de poucas células"],["Imagem de cálcio","TÉCNICA","a filmagem de atividade em células identificáveis"],["Lesão / TMS","INTERVENÇÃO","o teste de necessidade funcional"],["Análise","PROCESSO","a interpretação dos registros"],["Convergência","RACIOCÍNIO","vários ângulos apoiando a mesma explicação"]],"chain":["A hipótese define o que observar ou manipular.","O método coleta um tipo específico de sinal.","O sinal é processado e comparado.","Controles reduzem explicações alternativas.","Intervenções podem fortalecer inferências causais.","Convergência e replicação aumentam confiança."],"ifs":[["E se uma câmera registrasse movimento numa parte do evento, mas desligá-la não mudasse o evento?","A câmera mostraria associação, mas a equipe não poderia concluir que aquela parte era necessária para o acontecimento."],["E se dois instrumentos da equipe distorcessem o evento do mesmo jeito?","Os dois instrumentos da equipe devolveriam a mesma distorção; a concordância pareceria forte, mas não viria de ângulos independentes do evento."]],"limit":"Métodos não leem pensamentos diretamente. Toda conclusão depende do sinal medido, do desenho, dos controles e da análise.","keep":"A equipe escolhe instrumentos que enxergam coisas diferentes → compara os registros → testa o que muda ao intervir → e confia mais quando erros independentes apontam para o mesmo modelo."},"plasticidade":{"lead":"Como atividade repetida transforma uma conexão provisória em mudança duradoura?","hierarchy":["sinapse","AMPA e NMDA","entrada de Ca²⁺","CaMKII / PKA / CREB","síntese de proteínas","mudança estrutural"],"scene_title":"A rua que vira avenida","scene":["Imagine uma rua com faixas comuns sempre abertas e uma cancela lateral que só cede quando a rua já está cheia de carros. Quando ela cede, passa um sinal que permite pintar rapidamente outra faixa com o material que já está no local.","Se o movimento continua em sessões separadas, pedidos chegam a um depósito central. O depósito libera asfalto e concreto, mas seu estoque é limitado e precisa de tempo para ser reposto. Com material suficiente, a rua deixa de apenas funcionar melhor por alguns minutos e vira uma avenida estável."],"mapping":[["Sinapse","CONEXÃO","a rua"],["Glutamato","MOLÉCULA","os carros que chegam"],["AMPA","RECEPTOR","as faixas comuns"],["NMDA","RECEPTOR","a cancela que só cede com a rua cheia"],["Ca²⁺","ÍON / SINAL","o que atravessa a cancela"],["CaMKII","ENZIMA","a pintura rápida de outra faixa"],["PKA / CREB","SINALIZAÇÃO","o pedido que alcança o depósito"],["Síntese de proteínas","PROCESSO","a obra feita com asfalto e concreto do depósito"]],"chain":["Atividade coordenada despolariza a membrana.","A despolarização remove o bloqueio do NMDA.","A entrada de Ca²⁺ ativa vias de sinalização.","Proteínas existentes mudam rapidamente a eficácia sináptica.","Estimulação repetida recruta expressão gênica e síntese de proteínas.","Mudanças estruturais estabilizam parte do fortalecimento."],"ifs":[["E se a cancela abrisse com a rua vazia?","Qualquer carro isolado iniciaria uma obra, e a rua perderia a exigência de coincidência entre chegada e movimento já existente."],["E se o depósito tivesse estoque infinito?","Pedidos colados poderiam produzir avenida sem intervalo; como o estoque é limitado e se repõe com o tempo, sessões espaçadas encontram mais material disponível."]],"limit":"A síntese de proteínas não é um único depósito literal, e diferentes formas de plasticidade usam mecanismos e escalas de tempo parcialmente distintos.","keep":"A rua enche → a cancela cede → uma faixa pode ser pintada na hora → pedidos repetidos chegam ao depósito → o estoque reposto permite transformar a rua em avenida."}};

function buildImagineV2(d){
  const esc = (v)=>String(v).replace(/[&<>\"]/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  const hierarchy = d.hierarchy.map(esc).join(' <b>→</b> ');
  const mapping = d.mapping.map(row=>`<div class="im-row"><span class="im-t">${esc(row[0])}</span><span class="im-k">${esc(row[1])}</span><span class="im-d">${esc(row[2])}</span></div>`).join('');
  const chain = d.chain.map(x=>`<li>${esc(x)}</li>`).join('');
  const whatifs = d.ifs.map(x=>`<div class="im-wif"><p class="im-wq">${esc(x[0])}</p><p>${esc(x[1])}</p></div>`).join('');
  const scene = d.scene.map(x=>`<p>${esc(x)}</p>`).join('');
  return `<p class="im-lead">${esc(d.lead)}</p>
    <div class="im-h">Do grande para o pequeno</div>
    <div class="im-flow">${hierarchy}</div>
    <div class="im-h">A cena · ${esc(d.scene_title)}</div>
    ${scene}
    <div class="im-h">Quem é quem</div>
    <div class="im-tab">${mapping}</div>
    <div class="im-h">A cadeia causal</div>
    <ol class="im-chain">${chain}</ol>
    <div class="im-h">Rode a cena na cabeça</div>
    ${whatifs}
    ${d.limit ? `<div class="im-lim"><div class="im-limh">Onde a metáfora deixa de ser literal</div><p>${esc(d.limit)}</p></div>` : ''}
    <div class="im-keep">${esc(d.keep)}</div>`;
}

Object.keys(IMAGINE_DATA_V2).forEach(id=>{
  if(!IMAGINE[id]) IMAGINE[id] = buildImagineV2(IMAGINE_DATA_V2[id]);
});

function renderImagine(m){
  const host = document.getElementById('md-imagine');
  if(!host) return;
  const html = IMAGINE[m.id];
  if(!html){ host.innerHTML = ''; return; }
  host.innerHTML = `
    <div class="im-wrap">
      <button class="im-toggle" onclick="toggleImagine(event)" aria-expanded="false" aria-controls="im-body">
        <span class="im-kick">Extra</span>
        <span class="im-title">Imagine assim <span class="im-v2-badge">MODELO MENTAL</span></span>
        <span class="im-note">Categoria, hierarquia, cadeia causal e uma metáfora para organizar o módulo. Opcional \u2014 não conta para a conclusão do módulo.</span>
        <svg class="im-chev" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polyline points="6 9 12 15 18 9"></polyline></svg>
      </button>
      <div class="im-body" id="im-body" hidden>${html}</div>
    </div>`;
}

function toggleImagine(ev){
  if(ev) ev.stopPropagation();
  const panel = document.getElementById('im-body');
  if(!panel) return;
  const abrindo = panel.hasAttribute('hidden');
  if(abrindo){
    panel.removeAttribute('hidden');
    try{ glossify(panel); }catch(e){}
  } else panel.setAttribute('hidden','');
  const btn = ev ? ev.currentTarget : null;
  if(btn){
    btn.setAttribute('aria-expanded', abrindo ? 'true' : 'false');
    btn.classList.toggle('open', abrindo);
  }
}
